begin;
insert into public.ce_course3_resources(id,data) values
('course3_module11_pdf','{"base64": "", "sha256": "d311494df576817616b8769abc819b429887a25847afa24af6b159cf20d3ebf5", "filename": "CE_HALO_Course3_Module11_Sentinel_Events_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module11_questions','[{"module_id": "course_3_module_11", "question_id": "course_3_module_11_q01", "question_number": 1, "stem": "Per the 2024 Joint Commission Sentinel Event Policy, which of the following best defines a sentinel event?", "choice_a": "A patient safety event, not primarily related to the natural course of the patient''s underlying illness, that reaches a patient and results in death, permanent harm, or severe temporary harm", "choice_b": "A close call that did not reach the patient", "choice_c": "Any adverse event that receives media attention", "choice_d": "Any error that reaches the patient regardless of severity", "correct_choice": "a", "rationale": "The 2024 TJC policy defines a sentinel event as a patient safety event, not primarily related to the natural course of the underlying illness, that reaches a patient and results in death, permanent harm, or severe temporary harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q02", "question_number": 2, "stem": "Under the 2024 TJC Sentinel Event Policy, an organization has how many business days to complete the comprehensive systematic analysis and action plan after becoming aware of a sentinel event?", "choice_a": "30 calendar days", "choice_b": "55 business days", "choice_c": "90 calendar days", "choice_d": "45 business days", "correct_choice": "b", "rationale": "TJC requires the comprehensive systematic analysis and action plan within 55 business days of the organization becoming aware of the sentinel event.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q03", "question_number": 3, "stem": "Which of the following describes a close call (near miss)?", "choice_a": "A patient safety event that reached the patient and caused permanent harm", "choice_b": "A hazardous condition that has not yet caused any event", "choice_c": "A patient safety event that did not reach the patient", "choice_d": "A patient safety event that reached the patient without causing harm", "correct_choice": "c", "rationale": "A close call / near miss is a patient safety event that did not reach the patient (e.g., a medication error caught before administration). No-harm events reach the patient without causing harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q04", "question_number": 4, "stem": "RCA2 recommends that every action plan include at least one:", "choice_a": "Chart audit only", "choice_b": "New signage or reminder", "choice_c": "Weak action such as staff re-education", "choice_d": "Strong or intermediate action that reduces reliance on individual memory or vigilance", "correct_choice": "d", "rationale": "RCA2 explicitly recommends at least one strong or intermediate action per plan. Weak actions (education, policy alone, reminders) rarely prevent recurrence when used alone.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q05", "question_number": 5, "stem": "Per the Marx just-culture algorithm, which of the following is the most appropriate response to a clinician who committed a human error (an inadvertent slip)?", "choice_a": "Consoling the clinician and investigating the system factors that contributed to the error", "choice_b": "Formal discipline including termination", "choice_c": "Referral to the state licensing board", "choice_d": "Coaching the clinician about the risk of shortcuts", "correct_choice": "a", "rationale": "Human error should be met with consolation and system investigation. Coaching is the response to at-risk behavior; discipline is reserved for reckless conduct.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q06", "question_number": 6, "stem": "A CRNA repeatedly bypasses the smart-pump drug library because programming the correct concentration takes extra time. No patient has been harmed, and the CRNA believes the risk is low. Under the Marx model, this behavior is best characterized as:", "choice_a": "Reckless conduct", "choice_b": "At-risk behavior", "choice_c": "Sabotage", "choice_d": "Human error", "correct_choice": "b", "rationale": "At-risk behavior is a drift from safe procedure in which the clinician chose a shortcut but did not recognize the risk as significant. Coaching, addressing peer norms, and removing system incentives for the shortcut are the appropriate response.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q07", "question_number": 7, "stem": "Which of the following most accurately describes reckless conduct under the Marx just-culture model?", "choice_a": "A shortcut taken because it feels reasonable", "choice_b": "A slip caused by fatigue", "choice_c": "A conscious, unjustifiable disregard of a substantial and unjustifiable risk (e.g., knowingly practicing while impaired or falsifying documentation to hide an error)", "choice_d": "Any error that causes patient harm", "correct_choice": "c", "rationale": "Reckless conduct is a conscious, unjustifiable disregard of a substantial and unjustifiable risk. It is rare in healthcare adverse events and is the only category for which punitive discipline is the primary response.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q08", "question_number": 8, "stem": "The ''substitution test'' in just-culture analysis asks:", "choice_a": "Whether the involved clinician should be replaced", "choice_b": "Whether the equipment can be substituted", "choice_c": "Whether the patient can be substituted into a research study", "choice_d": "Whether three similarly trained, similarly experienced clinicians, placed in the same system context, would likely have made the same error", "correct_choice": "d", "rationale": "The substitution test asks whether peers with similar training and experience would likely have acted the same way in the same context; if yes, the analysis focuses on system factors.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q09", "question_number": 9, "stem": "Which of the following best describes the ''second victim'' phenomenon?", "choice_a": "A healthcare provider involved in an unanticipated adverse patient event who becomes traumatized by the event", "choice_b": "The family member of an injured patient", "choice_c": "A hospital administrator receiving a lawsuit", "choice_d": "A patient who is harmed by a subsequent adverse event", "correct_choice": "a", "rationale": "The second victim, as described by Wu (2000) and Scott et al. (2009), is a healthcare provider involved in an unanticipated adverse event who is traumatized by the experience.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q10", "question_number": 10, "stem": "Structured peer-support programs modeled on the University of Missouri forYOU / MISE program have been shown to:", "choice_a": "Eliminate the need for institutional disclosure", "choice_b": "Reduce the severity and duration of second-victim distress", "choice_c": "Increase disciplinary action against involved clinicians", "choice_d": "Replace formal RCA2 investigation", "correct_choice": "b", "rationale": "Trained peer-support programs reduce severity and duration of second-victim distress and support clinician recovery. They complement, not replace, RCA2 and disclosure.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q11", "question_number": 11, "stem": "Which of the following is a core step in the AHRQ CANDOR (Communication and Optimal Resolution) framework?", "choice_a": "Immediate financial settlement before investigation", "choice_b": "Waiting until litigation is filed before disclosing to the family", "choice_c": "Early, honest, empathic communication and disclosure to the patient and family, followed by investigation and resolution", "choice_d": "Referring the clinician for licensure discipline before analysis", "correct_choice": "c", "rationale": "CANDOR emphasizes early honest disclosure, second-victim support, investigation with RCA2 or equivalent, and resolution informed by the investigation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q12", "question_number": 12, "stem": "A CRNA is asked to speak with a family shortly after an anesthesia sentinel event. Which of the following is the most appropriate approach consistent with CANDOR and current risk-management guidance?", "choice_a": "Advise the family to obtain an attorney", "choice_b": "Immediately state that a specific team member caused the harm", "choice_c": "Refuse to discuss the event under any circumstance", "choice_d": "Provide honest factual information, express empathy for what the family is experiencing, avoid speculation about cause, and coordinate wording with the institutional disclosure team and risk management", "correct_choice": "d", "rationale": "Honest, empathic communication that avoids speculation and is coordinated with the institutional disclosure team is consistent with CANDOR, current standards, and legal guidance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q13", "question_number": 13, "stem": "Which of the following is TRUE about state apology statutes as of 2024?", "choice_a": "Approximately 39 states plus DC have apology statutes, but scope varies; many protect only expressions of sympathy, not statements of fault or explanation of cause", "choice_b": "Apology statutes have all been repealed", "choice_c": "No state has enacted any form of apology statute", "choice_d": "All 50 states protect a full apology including statements of fault", "correct_choice": "a", "rationale": "About 39 states plus DC have apology statutes. Full-apology protection (covering fault or cause) is uncommon; most are ''partial apology'' laws protecting only expressions of sympathy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q14", "question_number": 14, "stem": "Which federal statute created broad confidentiality protection for Patient Safety Work Product submitted to a listed Patient Safety Organization (PSO)?", "choice_a": "Health Insurance Portability and Accountability Act (HIPAA)", "choice_b": "Patient Safety and Quality Improvement Act of 2005 (PSQIA)", "choice_c": "Emergency Medical Treatment and Labor Act (EMTALA)", "choice_d": "Health Care Quality Improvement Act of 1986 (HCQIA)", "correct_choice": "b", "rationale": "PSQIA (42 USC §§299b-21 to 299b-26) created Patient Safety Work Product protection when information is properly reported to a federally listed PSO. HCQIA governs professional review actions and NPDB reporting.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q15", "question_number": 15, "stem": "A CRNA is involved in a case where a video laryngoscope malfunctioned during a difficult airway, contributing to a delayed intubation and severe hypoxic injury. Which of the following is the most appropriate action regarding the device?", "choice_a": "Return the device to the equipment room for immediate reuse", "choice_b": "Attempt to troubleshoot and repair the device before reporting", "choice_c": "Preserve the device intact, do not modify settings, document serial number and configuration, and coordinate MDR reporting under 21 CFR §803 through the institutional process", "choice_d": "Discard the device to prevent further harm", "correct_choice": "c", "rationale": "Devices involved in serious injury or death must be preserved intact for user-facility Medical Device Reporting (MDR) under 21 CFR §803. Serial number, lot, and configuration must be documented.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q16", "question_number": 16, "stem": "A CRNA notices, several hours after an anesthesia event, that an intraoperative medication was inadvertently omitted from the record. Which of the following is the correct approach?", "choice_a": "Insert the entry into the original record at the correct time so the record is consistent", "choice_b": "Do not add anything, as any addition creates liability", "choice_c": "Overwrite the record to reflect the actual medication history", "choice_d": "Add a clearly identified late entry, with the current date, time, and author, describing what was administered and when, without altering prior entries", "correct_choice": "d", "rationale": "Late entries clearly identified as such (with current date, time, and author) are appropriate and expected. Overwriting, deletion, or backdating destroys peer-review and record integrity and creates independent liability.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q17", "question_number": 17, "stem": "Which of the following is the current standard for confirming tracheal intubation and preventing unrecognized esophageal intubation?", "choice_a": "Sustained waveform capnography with the understanding that absent sustained end-tidal CO2 after intubation should be treated as esophageal intubation until proven otherwise", "choice_b": "Pulse oximetry alone", "choice_c": "Chest rise and bilateral breath sounds alone", "choice_d": "Direct visualization of the tube passing through the cords alone", "correct_choice": "a", "rationale": "Current ASA and APSF standards require sustained waveform capnography for tracheal confirmation. Ancillary signs are insufficient when capnography is available.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q18", "question_number": 18, "stem": "Which of the following is the strongest RCA2-consistent action to reduce wrong-site regional block events?", "choice_a": "New signage on block-cart", "choice_b": "Structured pre-block time-out with visible site mark and required two-source verification (chart + surgical site mark) immediately before needle insertion", "choice_c": "E-mail reminder to all block practitioners", "choice_d": "Annual education module", "correct_choice": "b", "rationale": "A structured pre-block time-out with visible site mark and required two-source verification is a system-level intermediate-to-strong action; the other options are weak (education, reminders, signage).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q19", "question_number": 19, "stem": "A CRNA involved in a sentinel event is asked to attend a formal peer-review meeting. Which of the following statements is most accurate about peer-review privilege?", "choice_a": "Personal e-mails and text messages from the CRNA about the event are automatically protected", "choice_b": "The medical record and all clinical documentation are protected from discovery by peer-review privilege", "choice_c": "Peer-review privilege generally protects committee proceedings and specified quality-review materials, but does not shield the underlying medical record; scope varies by state and federal law", "choice_d": "Peer-review privilege has been abolished at the federal level", "correct_choice": "c", "rationale": "Peer-review privilege applies to committee proceedings and specified quality-review materials; the medical record is not shielded. Federal (HCQIA, PSQIA) and state statutes define scope.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q20", "question_number": 20, "stem": "Which of the following reporting systems is most appropriate when a suspected drug quality problem contributes to an anesthesia adverse event?", "choice_a": "The state department of transportation", "choice_b": "A professional social-media platform", "choice_c": "The state board of nursing only", "choice_d": "FDA MedWatch, through https://www.fda.gov/medwatch, with parallel institutional and manufacturer notification", "correct_choice": "d", "rationale": "Drug and device quality problems are reported through FDA MedWatch. Parallel institutional and manufacturer notification is expected; user-facility Medical Device Reports under 21 CFR §803 apply for device-related death or serious injury.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q21", "question_number": 21, "stem": "Which of the following is NOT a strong or intermediate RCA2 action for reducing medication error involving neuromuscular blockers?", "choice_a": "A staff education e-mail alone", "choice_b": "Forcing-function packaging changes and separated storage", "choice_c": "Barcode verification and smart-pump drug libraries", "choice_d": "Independent double-check for high-alert medications", "correct_choice": "a", "rationale": "A staff education e-mail alone is a weak action. Packaging, storage, barcode, smart-pump, and independent verification are stronger interventions with better evidence of preventing recurrence.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q22", "question_number": 22, "stem": "Which of the following categories has consistently been identified in 2020–2024 TJC data as one of the two most frequent root-cause categories across all reviewable sentinel events?", "choice_a": "Weather", "choice_b": "Human factors and communication", "choice_c": "Language barriers only", "choice_d": "Insurance coverage", "correct_choice": "b", "rationale": "Human factors and communication are the two most frequently identified root-cause categories across TJC-reported reviewable events, reinforcing the primacy of briefings, time-outs, and structured handoffs.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q23", "question_number": 23, "stem": "A CRNA has just experienced an unexpected cardiac arrest and death during an anesthetic. The CRNA''s colleague offers to cover the remaining cases and suggests accessing the institution''s peer-support program. Which of the following is most consistent with current second-victim guidance?", "choice_a": "The CRNA should complete all scheduled cases to avoid appearing weak", "choice_b": "The CRNA should decline peer support to protect professional reputation", "choice_c": "The CRNA should accept coverage when clinically feasible, access peer support early, avoid making high-risk clinical decisions immediately after the event, and monitor for prolonged distress", "choice_d": "The CRNA should immediately resign from the anesthesia group", "correct_choice": "c", "rationale": "Accepting coverage when feasible, engaging peer support early, and avoiding immediate high-risk clinical decisions are consistent with the Scott et al. framework and current second-victim guidance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q24", "question_number": 24, "stem": "Which of the following statements about the CRNA''s role in an RCA2 interview is most accurate?", "choice_a": "The CRNA should modify recollection to minimize personal exposure", "choice_b": "The CRNA should present only opinions, not facts", "choice_c": "The CRNA should decline to speak because peer review is adversarial", "choice_d": "The CRNA should provide accurate, non-defensive factual information; identify system factors (workload, packaging, workflow, interruption); and keep peer-support conversations separate from the RCA2 process", "correct_choice": "d", "rationale": "An honest, system-focused factual account supports the RCA2 analysis, is protective within a just-culture model, and identifies the latent factors that drive corrective action.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_11", "question_id": "course_3_module_11_q25", "question_number": 25, "stem": "A CRNA working in a state with a ''partial apology'' statute wants to express empathy to a family after an adverse anesthesia event. Which of the following is the most appropriate approach?", "choice_a": "Express empathy for what the family is experiencing while avoiding speculation about cause, coordinate wording with the institutional disclosure team, and understand that state protection typically covers sympathy but not statements of fault", "choice_b": "Discuss the event openly on social media to be transparent", "choice_c": "Immediately admit fault to the family", "choice_d": "Say nothing to the family to avoid any legal exposure", "correct_choice": "a", "rationale": "Partial apology statutes typically protect expressions of sympathy but not statements of fault. Coordinated wording, empathy without speculation, and CANDOR-consistent disclosure are protective for patients and providers.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module11_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;